// 目标 rank4（Extra 取源 !O）；卡帧0 = MainSub05 入口，开场120帧为训练外壳缓冲。
// 章节入口、检查点、-9905 刷怪门控、掉落与出生动画按任务许可省略。
// 真实敌保持源 HP/判定/运动；训练外壳下敌与段控制均无敌。

const TIME_LIMIT: int = 1924;       // 120 缓冲 + 1800 窗口 + 4 启动余量
const OPENING_BUFFER: int = 120;
const LASER_ACTIVE: int = 26;       // 源线长32、长度上限128，速度5：约26帧到达上限

// GirlA04_at2: etEx 0x2 ANIM a=1 的 4*velocity 出生退位移在出生点保留；
// 源 0x200000 VELTIME(a=60, r=1.0, s=保留角) 从当前速1.0到1.0，无速度变化，
// 只起EX游标停驻作用；此处用60帧等待并在同帧回收母弹以腾出LASER。
xformdef RICE_TIMER {
    wait(60);
    set_life(1);
}

// GirlA04_at2 的 0x8000000 LASER（a=0 线激光，b=8，c=6，d=1 删除父弹）：
// 源在60帧后于母弹当前位置沿母弹角建线，长32、宽16（目标恒宽近似8）、速度5。
async sub rice_to_laser() {
    wait(59);                        // 弹任务出生晚一帧，与xform第60帧对齐
    var beam: int = laser(6, $self_x, $self_y, $self_angle,
                          0fx, 8fx, 0, LASER_ACTIVE, 0);
    if beam >= 0 {
        lz_speed(beam, 5fx, 32fx);   // 从近端长出32，之后以5px/帧前移
    }
}

// GirlA04_at2 主循环：源 etAim(0,1) 固定方向三路扇（0,-30,+30度），
// 每20帧一次、共80次；每波抽一次 ANGLE_PLAYER + RANDF2*3度。
async sub girl_shoot() {
    wait(10 + rand(40));             // 源 wait(10 + RAND%40)
    var B: int = 80;                 // 源 $B=80; if ($B--) 共执行80次
    while B > 0 {
        var aim: angle = aim_player();
        var off: int = (rand(65536) - 32768) * 5461 / 32768; // RANDF2*3度
        var base: angle = aim + (off as angle);
        var k: int = 0;
        while k < 3 {
            var a: angle = base;
            if k == 1 { a = base - 30deg; }
            if k == 2 { a = base + 30deg; }
            // ANIM 退位移 position -= 4*velocity，速度1故沿弹角回退4px
            var sx: fx = $self_x - 4fx * cos(a);
            var sy: fx = $self_y - 4fx * sin(a);
            _ = fire(TH15_RICE, 6, sx, sy, 1fx, a, RICE_TIMER, rice_to_laser);
            k = k + 1;
        }
        wait(20);
        B = B - 1;
    }
}

// GirlA04_at: setHurtbox(24,24)->12, setHitbox(16,16)->8；
// moveVel(%F0,3) 后 moveVelTime(120,1,-11.25度,2) 与 wait(120)，
// 再 moveVelTime(60,4,45度,4)，随后进入 wait(1000) 循环（速度插值继续推进）。
// mir=1 对应 enmCreateM 的子镜像初值1：仅X向镜像运动角。
async sub girl_main(a1: angle, mir: int) {
    set_invuln(65535);               // 训练外壳：真实敌无敌
    set_hurtbox(12fx);
    set_hitbox(8fx);
    spawn girl_shoot();              // 源 @GirlA04_at2() async
    var s1: int = a1 as int;
    var s2: int = -2048;             // -0.19634955 rad = -11.25度
    var s3: int = 8192;              // 0.7853982 rad = 45度
    if mir != 0 {
        s1 = 32768 - s1;             // 镜像：方向 (x,y) -> (-x,y)
        s2 = 32768 - s2;
        s3 = 32768 - s3;
    }
    move_vel(0, s1 as angle, 3fx, EASE_LINEAR);
    move_vel(120, s2 as angle, 2fx, EASE_QUAD_IN);
    wait(120);
    move_vel(60, s3 as angle, 4fx, EASE_QUAD_OUT);
    loop { wait(1000); }
}

// MainSub05: wait(80)，然后六大轮；每轮左6只(10帧间隔)、30帧、右6只(10帧间隔)、30帧。
// 左 enmCreate x=-224、右 enmCreateM x=+224；y=64+RANDF2*32；F0=22.5deg+RANDF2*20deg。
sub spawn_left() {
    var a1: int = 4096 + (rand(65536) - 32768) * 3641 / 32768;
    var y: fx = 64fx + ((rand(65536) - 32768) as fx) / 1024fx;
    _ = spawn_enemy(-224fx, y, 50, 0, 1000, 0, girl_main(a1 as angle, 0));
}

sub spawn_right() {
    var a1: int = 4096 + (rand(65536) - 32768) * 3641 / 32768;
    var y: fx = 64fx + ((rand(65536) - 32768) as fx) / 1024fx;
    _ = spawn_enemy(224fx, y, 50, 0, 1000, 0, girl_main(a1 as angle, 1));
}

async sub pattern() {
    wait(OPENING_BUFFER);            // 训练外壳开场缓冲
    wait(80);                        // 源 MainSub05 首 wait
    for round in 0..6 {
        for i in 0..6 {
            spawn_left();
            wait(10);
        }
        wait(30);
        for j in 0..6 {
            spawn_right();
            wait(10);
        }
        wait(30);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

